import React, { useState } from "react"; // Убрал лишний 'use' из импорта
import Header from "./components/Header";
import Footer from "./components/Footer";
import Items from "./components/Items";
import Categories from "./components/Categories";

function App() {
  const [items] = useState([
    { id: 1, title: 'Hoodie', img: 'HoodieGray.jpg', desc: 'Comfort + Whyte Style.', category: 'Zip', price: '49.99' },
    { id: 2, title: 'Jacket', img: 'jacketWhite.jpg', desc: 'Jacket for StreatWear.', category: 'Jacket', price: '149.00' },
    { id: 3, title: 'Hoodie Baggy', img: 'HoodieBlue.jpg', desc: 'Fresh and Ice.', category: 'Hoodie', price: '69.99' },

  ]);

  // 1. Инициализируем текущие товары основным списком items
  const [currentItems, setCurrentItems] = useState(items); 
  const [orders, setOrders] = useState([]);

  const addToOrder = (item) => {
    let isInArray = false;
    orders.forEach(el => {
      if(el.id === item.id) isInArray = true;
    });
    if(!isInArray) {
      setOrders([...orders, item]);
    }
  };

  const deleteOrder = (id) => {
    setOrders(orders.filter(el => el.id !== id));
  }

  // 2. Логика фильтрации
  const chooseCategory = (category) => {
    if (category === 'all') {
      setCurrentItems(items); // Показываем все
      return;
    }
    // Оставляем только те, что подходят по категории
    setCurrentItems(items.filter(el => el.category === category));
  }

  return (
    <div className="wrapper">
      <Header orders={orders} onDelete={deleteOrder}/>
      <Categories chooseCategory={chooseCategory}/>
      {/* 3. Передаем именно currentItems, а не items */}
      <Items items={currentItems} onAdd={addToOrder}/>
      <Footer />
    </div>
  );
}

export default App;
